#include <unordered_map>
#include <vector>
#include <string>
#include <optional>
#include <algorithm>
struct Value{int value,version;};struct Entry{int value,version,expires,stamp;bool dirty;};struct Op{std::string kind,key;int value;};class CacheModel {public:std::unordered_map<std::string,Value>db{{"a",{1,0}},{"b",{2,0}}};std::unordered_map<std::string,Entry>cache;std::vector<std::optional<int>>reads;int lost=0,clock=0;void flush(const std::string& k,Entry& e){if(e.dirty){db[k]={e.value,e.version};e.dirty=false;}}void put(const std::string& k,Entry e,int capacity){cache.erase(k);if((int)cache.size()>=capacity){auto old=std::min_element(cache.begin(),cache.end(),[](const auto& a,const auto& b){return a.second.stamp<b.second.stamp;});flush(old->first,old->second);cache.erase(old);}e.stamp=++clock;cache[k]=e;}
void run(const std::vector<Op>& ops,const std::string& strategy,int capacity,int ttl,bool loseInvalidation){for(unsigned tick=0;tick<ops.size();tick++){for(auto it=cache.begin();it!=cache.end();)if(it->second.expires<=(int)tick){flush(it->first,it->second);it=cache.erase(it);}else ++it;auto op=ops[tick];auto k=op.key;if(op.kind=="read"){if(cache.count(k))cache[k].stamp=++clock;else if(db.count(k)){auto v=db[k];put(k,{v.value,v.version,int(tick)+ttl,0,false},capacity);}reads.push_back(cache.count(k)?std::optional<int>(cache[k].value):std::nullopt);}else if(op.kind=="write"){int version=std::max(db.count(k)?db[k].version:0,cache.count(k)?cache[k].version:0)+1;if(strategy=="write-back")put(k,{op.value,version,int(tick)+ttl,0,true},capacity);else{db[k]={op.value,version};if(strategy=="write-through")put(k,{op.value,version,int(tick)+ttl,0,false},capacity);else if(!loseInvalidation)cache.erase(k);}}else if(op.kind=="invalidate"){if(cache.count(k))flush(k,cache[k]);cache.erase(k);}else if(op.kind=="crash"){for(const auto& [key,e]:cache)lost+=e.dirty;cache.clear();}}}};
